FUNCTION SAFE_DIV (P_NUMERATOR IN NUMBER, P_DENOMINATOR IN NUMBER) RETURN NUMBER IS
  V_RESULT NUMBER;
  DIVIDE_BY_ZERO_LOCAL EXCEPTION;
BEGIN
  IF P_DENOMINATOR = 0 THEN
    RAISE DIVIDE_BY_ZERO_LOCAL;
  END IF;
  V_RESULT := P_NUMERATOR / P_DENOMINATOR;
  RETURN V_RESULT;
EXCEPTION
  WHEN ZERO_DIVIDE THEN
    RETURN NULL;
  WHEN OTHERS THEN
    RAISE_APPLICATION_ERROR(-20001, 'Unexpected error in SAFE_DIV');
END SAFE_DIV;
